55	const PROCESSING_FEE = 5;
56	
57	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
58	
59	const BASE_PREMIUMS = {
60	  sword: 100,
61	  amulet: 60,
62	  staff: 80,
63	  potion: 40,
64	  rune: 25,
65	  moonstone: 25,
66	} as const satisfies Record<string, number>;
67	
68	type PricedItemType = keyof typeof BASE_PREMIUMS;
69	
70	const hasBasePremium = (type: string): type is PricedItemType =>
71	  type in BASE_PREMIUMS;
72	
73	// Unknown item types are not yet rejected — the spec requires an error, but no
74	// test drives that behaviour yet, so they are priced at 0 for the moment.
75	const UNPRICED_UNKNOWN_TYPE = 0;
76	
77	const basePremiumForItem = (item: Item): number =>
78	  hasBasePremium(item.type)
79	    ? BASE_PREMIUMS[item.type]
80	    : UNPRICED_UNKNOWN_TYPE;
81	
82	const BLOCK_SIZE = 3;
83	
84	const BLOCK_BASE_PREMIUM = 60;
85	
86	// A block is not carved out of a larger group: the block price applies only
87	// when the group consists of exactly three alike components (7 runes cost
88	// 7 × 25, not 60 + 60 + 25). Alikeness is guaranteed by the caller, which only
89	// ever passes a single group from groupByType.
90	const isExactlyOneBlock = (group: Item[]): boolean =>
91	  group.length === BLOCK_SIZE;
92	
93	const sum = (amounts: number[]): number =>
94	  amounts.reduce((total, amount) => total + amount, 0);
95	
96	// "Alike" means the same exact type, not merely the same family: two runes and
97	// a moonstone are three components but not three alike ones, so grouping them
98	// by type keeps them apart and denies them the block price.
99	const groupByType = (items: Item[]): Item[][] => {
100	  const groups = new Map<string, Item[]>();
101	  for (const item of items) {
102	    groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
103	  }
104	  return [...groups.values()];
105	};
106	
107	const basePremiumForGroup = (group: Item[]): number =>
108	  isExactlyOneBlock(group)
109	    ? BLOCK_BASE_PREMIUM
110	    : sum(group.map(basePremiumForItem));
111	
112	const basePremiumForItems = (items: Item[]): number =>
113	  sum(groupByType(items).map(basePremiumForGroup));
114	
115	const CURSE_SURCHARGE = 0.5;
116	
117	// Every modifier is an additive percentage of its OWN base — modifiers never
118	// compound with each other. Item-scoped modifiers take the affected item's base
119	// premium as their base; policy-scoped modifiers take the policy base premium
120	// (the sum of all item base premiums). So the total is always
121	// base + Σ (rate × that modifier's base), never a product of (1 + rate) factors.
122	const modifierAmount = (rate: number, base: number): number => rate * base;
123	
124	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
125	
126	const HIGH_ENCHANTMENT_THRESHOLD = 5;
127	
128	const isCursed = (item: Item): boolean => item.cursed === true;
129	
130	const isHighlyEnchanted = (item: Item): boolean =>
131	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
132	
133	interface ItemModifier {
134	  rate: number;
135	  appliesTo: (item: Item) => boolean;
136	}
137	
138	// Each item-scoped modifier is a row: a rate and the condition under which it
139	// applies. The predicate names the modifier, so a row needs no separate label.
140	// Adding a modifier means adding a row, not a new branch.
141	const ITEM_MODIFIERS: ItemModifier[] = [
142	  { rate: CURSE_SURCHARGE, appliesTo: isCursed },
143	  { rate: HIGH_ENCHANTMENT_SURCHARGE, appliesTo: isHighlyEnchanted },
144	];
145	
146	const itemModifierRates = (item: Item): number[] =>
147	  ITEM_MODIFIERS.filter((modifier) => modifier.appliesTo(item)).map(
148	    (modifier) => modifier.rate,
149	  );
150	
151	const LOYALTY_DISCOUNT = 0.2;
152	
153	const LOYALTY_THRESHOLD_YEARS = 2;
154	
155	const isLongStanding = (customer: Customer): boolean =>
156	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
157	
158	// Discounts are surcharges with the sign flipped: expressing one as a negative
159	// rate lets it flow through the same additive sum as every surcharge, with no
160	// separate subtraction step. Discount constants stay positive magnitudes and
161	// are negated here, at the point of use, so the direction is visible in the
162	// rate list rather than buried in a constant's sign.
163	const asDiscount = (rate: number): number => -rate;
164	
165	// Policy-scoped modifiers apply to the policy base premium. Unlike item
166	// modifiers they select on the customer rather than on an item.
167	const policyModifierRates = (customer: Customer): number[] => [
168	  INITIAL_ASSESSMENT_SURCHARGE,
169	  ...(isLongStanding(customer) ? [asDiscount(LOYALTY_DISCOUNT)] : []),
170	];
171	
172	const itemModifiersTotal = (items: Item[]): number =>
173	  sum(
174	    items.flatMap((item) =>
175	      itemModifierRates(item).map((rate) =>
176	        modifierAmount(rate, basePremiumForItem(item)),
177	      ),
178	    ),
179	  );
180	
181	const policyModifiersTotal = (
182	  policyBasePremium: number,
183	  customer: Customer,
184	): number =>
185	  sum(
186	    policyModifierRates(customer).map((rate) =>
187	      modifierAmount(rate, policyBasePremium),
188	    ),
189	  );
190	
191	const quotePremium = (items: Item[], customer: Customer): number => {
192	  const policyBasePremium = basePremiumForItems(items);
193	  return Math.round(
194	    policyBasePremium +
195	      itemModifiersTotal(items) +
196	      policyModifiersTotal(policyBasePremium, customer) +
197	      PROCESSING_FEE,
198	  );
199	};
200	
201	const runStep = (step: Step, customer: Customer): StepResult => {
202	  if (step.op === "quote")
203	    return { premium: quotePremium(step.items, customer) };
204	  throw new Error(`Unsupported step: ${step.op}`);
205	};
206	
207	export const runScenario = (scenario: Scenario): ScenarioResult => ({
208	  results: scenario.steps.map((step) => runStep(step, scenario.customer)),
209	});
